<?php
namespace App\Models;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
final class TariffVersion extends Model{use HasUuids;protected$fillable=['insurance_product_id','version','effective_from','effective_until','status','input_schema','rules','rules_hash','created_by','approved_by','approved_at','approval_reason','regulatory_reference'];protected function casts():array{return['effective_from'=>'date','effective_until'=>'date','input_schema'=>'array','rules'=>'array','approved_at'=>'datetime'];}public function product():BelongsTo{return$this->belongsTo(InsuranceProduct::class,'insurance_product_id');}public function creator():BelongsTo{return$this->belongsTo(User::class,'created_by');}public function approver():BelongsTo{return$this->belongsTo(User::class,'approved_by');}}
